	createFeedsManagerChainConfig(input: $input) {
		__typename
		... on CreateFeedsManagerChainConfigSuccess {
			chainConfig {
				id
				chainID
				chainType
				accountAddr
				adminAddr
				fluxMonitorJobConfig {
					enabled
				}
				ocr1JobConfig {
					enabled
					isBootstrap
					multiaddr
					p2pPeerID
					keyBundleID
				}
				ocr2JobConfig {
					enabled
					isBootstrap
					multiaddr
					forwarderAddress
					p2pPeerID
					keyBundleID
					plugins {
						commit
						execute
						median
						mercury
						rebalancer
					}
				}
			}
		}
		... on NotFoundError {
			message
			code
		}
		... on InputErrors {
			errors {
				message
				path
			}
		}
	}
}
